"""Canonical vendor-neutral taxonomy."""
from copy import deepcopy
DOMAINS=tuple({"domain_id":x[0],"name":x[1],"description":x[2]} for x in [["energy_systems","Energy Systems","Resources, conversion, generation, storage and end use."],["electricity_generation","Electricity Generation","Thermal, hydro, nuclear, renewable and distributed generation."],["power_transmission_distribution","Power Transmission and Distribution","Grid, substations, distribution and interconnection."],["renewable_energy","Renewable Energy","Solar, wind, geothermal, ocean and other renewables."],["solar_energy","Solar Energy","Photovoltaic, concentrated, rooftop and utility solar."],["wind_energy","Wind Energy","Onshore, offshore and wind-farm systems."],["hydropower","Hydropower","Hydroelectric and pumped-storage systems."],["nuclear_energy","Nuclear Energy","Generation, fuel cycle, safety and decommissioning."],["fossil_fuels","Fossil Fuels","Coal, petroleum, natural gas and transition systems."],["bioenergy_hydrogen","Bioenergy and Hydrogen","Biomass, biogas, biofuels and hydrogen."],["energy_storage","Energy Storage","Battery, pumped hydro, thermal and mechanical storage."],["energy_efficiency","Energy Efficiency","Efficient buildings, industry, appliances and demand."],["smart_grids_microgrids","Smart Grids and Microgrids","Grid digitization, microgrids and demand response."],["electric_mobility_charging","Electric Mobility and Charging","EV charging and vehicle-grid integration."],["energy_markets_trading","Energy Markets and Trading","Wholesale, retail, balancing and market design."],["energy_access_electrification","Energy Access and Electrification","Universal access and rural electrification."],["water_supply_treatment","Water Supply and Treatment","Water sourcing, purification and potable supply."],["wastewater_sanitation","Wastewater and Sanitation","Sewage, wastewater treatment, reuse and sanitation."],["water_resources_hydrology","Water Resources and Hydrology","Watersheds, groundwater and water allocation."],["solid_waste_circularity","Solid Waste and Circularity","Collection, recycling, recovery and circular materials."],["air_quality_emissions","Air Quality and Emissions","Air monitoring, pollutants and emissions mitigation."],["climate_science_adaptation","Climate Science and Adaptation","Climate risks, resilience and adaptation."],["environmental_protection","Environmental Protection","Environmental monitoring, prevention and remediation."],["biodiversity_ecosystems","Biodiversity and Ecosystems","Habitats, conservation and ecosystem services."],["forests_land_restoration","Forests and Land Restoration","Forestry, land use, soil and restoration."],["marine_coastal_environment","Marine and Coastal Environment","Oceans, coasts, wetlands and marine pollution."],["environmental_impact_assessment","Environmental Impact Assessment","EIA, strategic assessment and mitigation."],["pollution_control_remediation","Pollution Control and Remediation","Contaminated land, releases and remediation."],["environmental_law_governance","Environmental Law and Governance","Policy, regulation and compliance frameworks."],["sustainability_esg_disclosure","Sustainability and ESG Disclosure","Metrics, reporting, assurance and disclosure."],["carbon_management_markets","Carbon Management and Markets","GHG accounting, pricing, removals and offsets."],["resource_efficiency_materials","Resource Efficiency and Materials","Material efficiency and responsible sourcing."],["environmental_health_safety","Environmental Health and Safety","Environmental health and safety management."],["disaster_resilience_emergency","Disaster Resilience and Emergency","Flood, drought, wildfire and industrial resilience."],["energy_environment_research","Energy and Environment Research","Research, laboratories and innovation."],["energy_utilities_data_digital","Energy and Utilities Data and Digital","Metering, telemetry, GIS, SCADA metadata and analytics."],["infrastructure_asset_lifecycle","Infrastructure and Asset Lifecycle","Planning, engineering, construction and decommissioning."],["utility_customer_services","Utility Customer Services","Metering interfaces and consumer services."],["energy_water_nexus","Energy-Water Nexus","Energy, water and ecosystem interdependencies."],["just_transition_community","Just Transition and Community","Affordability, workforce transition and participation."]])
def list_domains(): return deepcopy(list(DOMAINS))
def get_domain(domain_id):
 k=domain_id.strip().casefold(); return next((deepcopy(x) for x in DOMAINS if x["domain_id"].casefold()==k),None)
def search_domains(keyword):
 k=keyword.strip().casefold(); return [deepcopy(x) for x in DOMAINS if k and k in " ".join(x.values()).casefold()]
def validate_domains():
 ids=[x["domain_id"] for x in DOMAINS]; return {"valid":len(ids)==len(set(ids)),"count":len(ids)}
